{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C01","C05","C07","C08","C12","C18","C24","C51","C54","C56","C58"],
  "contradictory_card_ids": ["C16","C22"],
  "prediction_basis_card_ids": ["C01","C05","C07","C08","C12","C18","C24","C51","C54","C56","C58"],
  "claims": [
    {
      "claim": "Direct human absolute-bioavailability measurements in the most transferable contexts are all above the 20% threshold: imidafenacin 57.8%, tolvaptan 56%, ACT-1004-1239 53%, bromazepam 86%, and lenvatinib ~85%.",
      "card_ids": ["C01","C05","C08","C07","C12"]
    },
    {
      "claim": "The closest structural contexts to the query, a benzamide/indazole (venadaparib) and a lipophilic benzamide (tolvaptan), are high-F; venadaparib also showed 70.63% oral F in mice and tolvaptan's 56% F is not affected by food, supporting the fasted condition.",
      "card_ids": ["C18","C24","C05","C21"]
    },
    {
      "claim": "L4 piroxicam records show near-complete human absorption (fa ~100%) and negligible first-pass metabolism despite aqueous solubility of only 14.27 µg/mL, indicating that low aqueous solubility does not by itself preclude F >= 20%.",
      "card_ids": ["C56","C58","C51","C54","C48"]
    },
    {
      "claim": "Other L4 solubility records (hydrazinocurcumin 4-5 µg/mL, nitazoxanide 7.55 µg/mL, compound II 12.5 µg/mL, compound 4 2.9 µg/mL at pH 7.4) are low but lack F measurements and therefore do not affirmatively establish F < 20% for the query.",
      "card_ids": ["C49","C53","C59","C50"]
    },
    {
      "claim": "The apatinib L2 10-20% value conflicts with its L1 'good' label and lacks species/dose/formulation/comparator detail; ilomastat's poor F is a peptidomimetic hydroxamic acid context with low structural transfer. Neither affirmatively establishes F < 20% for the query.",
      "card_ids": ["C22","C16"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C48","C49","C50","C51","C52","C53","C54","C55","C56","C57","C58","C59"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental absolute oral bioavailability value for the query molecule.",
    "No query-specific fasted-state solubility, dissolution, or permeability data.",
    "L4 records are for other molecules and mostly report solubility or fraction absorbed, not systemic F; transfer is limited by structural and formulation differences.",
    "L3 oral Cmax/AUC records lack IV comparators, so they cannot quantify F or confirm the F >= 20% threshold.",
    "Apatinib L2 low value lacks species, dose, formulation, and comparator detail and conflicts with its L1 'good' label.",
    "Most context records are not explicitly fasted; tolvaptan food independence and ARRY-403 fasted data only partially address this."
  ],
  "decision_summary": "Predicted high: F >= 20% remains better supported by multiple transferable direct human absolute-bioavailability contexts, especially the benzamide/indazole and lipophilic benzamide scaffolds (venadaparib, tolvaptan, imidafenacin, ACT-1004-1239, bromazepam, lenvatinib), reinforced by L2 preclinical values above 20%. The new L4 absorption/solubility records are consistent with oral absorption (piroxicam fa ~100% despite low aqueous solubility) and do not provide affirmative evidence for F < 20%. Apatinib's conflicting 10-20% L2 value and ilomastat's poor-F context are low-transferability and do not overturn the decision. Solubility/lipophilicity risks remain an uncertainty, not endpoint proof."
}

